package com.kaymlyn.planeteater.simulation.celestial.planetoid;

import com.kaymlyn.planeteater.simulation.physics.Vector3D;
import com.kaymlyn.planeteater.simulation.resources.Composition;
import com.kaymlyn.planeteater.simulation.resources.Material;
import lombok.Getter;
import lombok.Setter;

/**
 * Represents a satellite orbiting a celestial body
 * Can be natural (moons) or artificial (space stations, satellites)
 *
 * Generated by Claude (Sonnet 4.5)
 */
@Getter
@Setter
public class NaturalSatellite{

    public enum SatelliteType {
        NATURAL_MOON,           // Natural satellite (moon)
        SPACE_STATION,          // Large artificial structure
        COMMUNICATIONS,         // Communications satellite
        OBSERVATION,            // Telescope/sensor platform
        MINING_STATION,         // Orbital mining facility
        DEFENSE,                // Defensive platform
        LAGRANGE_STATION        // Station at a Lagrange point
    }

    private SatelliteType type;
    private String parentBodyId;        // ID of body this satellite orbits
    private boolean isArtificial;
    private double orbitalRadius;       // Distance from parent body
    private Composition inventory;      // For stations that store resources
    private Composition composition;    // For Natural Satellites

    public NaturalSatellite(String id, Vector3D position, Vector3D velocity,
                            Composition composition, Composition inventory, SatelliteType type,
                            String parentBodyId, boolean isArtificial) {

        this.type = type;
        this.parentBodyId = parentBodyId;
        this.isArtificial = isArtificial;
        this.orbitalRadius = 0.0;
        this.inventory = inventory;
        this.composition = composition;
    }

    /**
     * Create a natural moon
     */
    public static NaturalSatellite createMoon(String id, Vector3D position, Vector3D velocity,
                                              double radius, String parentBodyId) {
        Composition comp = new Composition();
        double volume = (4.0 / 3.0) * Math.PI * Math.pow(radius, 3);

        // Moon-like composition (similar to asteroids)
        comp.addMaterialAsVolume(Material.SILICA, Material.SILICA.massForVolume(volume * 0.45));
        comp.addMaterialAsVolume(Material.IRON, Material.IRON.massForVolume(volume * 0.25));
        comp.addMaterialAsVolume(Material.MAGNESIUM_OXIDE, Material.MAGNESIUM_OXIDE.massForVolume(volume * 0.20));
        comp.addMaterialAsVolume(Material.ALUMINUM_OXIDE, Material.ALUMINUM_OXIDE.massForVolume(volume * 0.10));

        return new NaturalSatellite(id, position, velocity, comp, new Composition(),
                SatelliteType.NATURAL_MOON, parentBodyId, false);
    }

    /**
     * Create an ice moon (like Europa or Enceladus)
     */
    public static NaturalSatellite createIceMoon(String id, Vector3D position, Vector3D velocity,
                                                 double radius, String parentBodyId) {
        Composition comp = new Composition();
        double volume = (4.0 / 3.0) * Math.PI * Math.pow(radius, 3);

        // Ice moon composition
        comp.addMaterialAsVolume(Material.WATER_ICE, Material.WATER_ICE.massForVolume(volume * 0.60));
        comp.addMaterialAsVolume(Material.SILICA, Material.SILICA.massForVolume(volume * 0.25));
        comp.addMaterialAsVolume(Material.IRON, Material.IRON.massForVolume(volume * 0.10));
        comp.addMaterialAsVolume(Material.AMMONIA_ICE, Material.AMMONIA_ICE.massForVolume(volume * 0.05));

        return new NaturalSatellite(id, position, velocity, comp, new Composition(),
                SatelliteType.NATURAL_MOON, parentBodyId, false);
    }

    /**
     * Create a space station
     */
    public static NaturalSatellite createSpaceStation(String id, Vector3D position, Vector3D velocity,
                                                      String parentBodyId) {
        Composition comp = new Composition();

        // Station construction materials
        comp.addMaterialAsRawMass(Material.ALUMINUM, 5e6);      // 5,000 tons
        comp.addMaterialAsRawMass(Material.TITANIUM, 2e6);      // 2,000 tons
        comp.addMaterialAsRawMass(Material.IRON, 3e6);          // 3,000 tons
        comp.addMaterialAsRawMass(Material.SILICA, 5e5);        // 500 tons (shielding)

        return new NaturalSatellite(id, position, velocity, new Composition(), comp,
                SatelliteType.SPACE_STATION, parentBodyId, true);
    }

    /**
     * Create a Lagrange point station
     * Stations at L4 or L5 are gravitationally stable
     */
    public static NaturalSatellite createLagrangeStation(String id, Vector3D position, Vector3D velocity,
                                                         String parentBodyId) {
        Composition comp = new Composition();

        // Larger construction for semi-permanent installation
        comp.addMaterialAsRawMass(Material.ALUMINUM, 1e7);      // 10,000 tons
        comp.addMaterialAsRawMass(Material.TITANIUM, 5e6);      // 5,000 tons
        comp.addMaterialAsRawMass(Material.IRON, 5e6);          // 5,000 tons
        comp.addMaterialAsRawMass(Material.SILICA, 2e6);        // 2,000 tons

        return new NaturalSatellite(id, position, velocity, new Composition(), comp,
                SatelliteType.LAGRANGE_STATION, parentBodyId, true);
    }

    /**
     * Create a mining station
     */
    public static NaturalSatellite createMiningStation(String id, Vector3D position, Vector3D velocity,
                                                       String parentBodyId) {
        Composition comp = new Composition();

        // Mining station with processing equipment
        comp.addMaterialAsRawMass(Material.IRON, 1e7);          // 10,000 tons
        comp.addMaterialAsRawMass(Material.ALUMINUM, 3e6);      // 3,000 tons
        comp.addMaterialAsRawMass(Material.TITANIUM, 2e6);      // 2,000 tons

        return new NaturalSatellite(id, position, velocity, new Composition(), comp,
                SatelliteType.MINING_STATION, parentBodyId, true);
    }

    /**
     * Add resources to station inventory (for artificial satellites)
     */
    public void addToInventory(Material material, double mass) {
        if (isArtificial) {
            inventory.addMaterialAsRawMass(material, mass);
        }
    }

    /**
     * Remove resources from station inventory
     */
    public double removeFromInventory(Material material, double mass) {
        if (isArtificial) {
            return inventory.removeMaterial(material, mass);
        }
        return 0.0;
    }

    /**
     * Get inventory capacity (artificial satellites only)
     */
    public double getInventoryCapacity() {
        if (!isArtificial) return 0.0;

        // Capacity scales with station mass
        switch (type) {
            case SPACE_STATION:
                return getMass() * 2.0; // Can store 2x its own mass
            case MINING_STATION:
                return getMass() * 5.0; // Can store 5x its own mass
            case LAGRANGE_STATION:
                return getMass() * 3.0; // Can store 3x its own mass
            default:
                return getMass() * 0.5;
        }
    }

    /**
     * Check if satellite is at a Lagrange point
     */
    public boolean isAtLagrangePoint() {
        return type == SatelliteType.LAGRANGE_STATION;
    }

    /**
     * For natural satellites, check if it's tidally locked
     * (orbital period = rotational period, always shows same face)
     */

    public double getMass() {
        return getInventory().getTotalMass() + getMass();
    }

    public double getRadius() {
        double volume = composition.getTotalVolume();
        return Math.cbrt((3.0 * volume) / (4.0 * Math.PI));
    }

    public double getDensity() {
        return 0;
    }

    @Override
    public String toString() {
        return String.format("Satellite[id=%s, type=%s, parent=%s, artificial=%s, " +
                        "mass=%.3e kg, radius=%.1f m, inventory=%.3e kg]",
                type, parentBodyId, isArtificial,
                getMass(), getRadius(), inventory.getTotalMass());
    }
}